const historico = [
  { est: 2, real: 3 },
  { est: 5, real: 9 },
  { est: 3, real: 4 },
  { est: 1, real: 2 },
];

const fatores = historico.map((h) => h.real / h.est).sort((a, b) => a - b);
console.log(fatores.map((f) => f.toFixed(2)).join(' '));

const nova = 4;
const menor = Math.round(nova * fatores[0]!);
const maior = Math.round(nova * fatores.at(-1)!);
console.log(`faixa: ${menor} a ${maior} dias`);

